  1	// Orchestration tests — fake in-process participants (no spawning), plus a REAL
  2	// git repo in a temp dir to verify the read-only worktree isolation invariant.
  3	
  4	import { test } from "node:test";
  5	import assert from "node:assert/strict";
  6	import { mkdtemp, writeFile, readFile, rm } from "node:fs/promises";
  7	import { join } from "node:path";
  8	import { tmpdir } from "node:os";
  9	import { execFile } from "node:child_process";
 10	import { promisify } from "node:util";
 11	import { runDebate, runFinalize, runContinuation, parseRespondeoStatus } from "../src/debate.ts";
 12	import type { Participant, AgentResult } from "../src/adapters.ts";
 13	
 14	const execFileAsync = promisify(execFile);
 15	
 16	function fake(id: string, vendor: string, run: Participant["run"]): Participant {
 17	  return { id, vendor, display: id, run };
 18	}
 19	const ok = (text: string): AgentResult => ({ ok: true, text, costUsd: 0.5 });
 20	const fail = (error: string): AgentResult => ({ ok: false, error });
 21	
 22	test("abort: <2 successful proposals ends the debate before any reaction round", async () => {
 23	  let reactions = 0;
 24	  const a = fake("a", "v1", async (prompt) => {
 25	    if (prompt.includes("debate so far")) reactions++;
 26	    return ok("proposal A");
 27	  });
 28	  const b = fake("b", "v2", async () => fail("timeout"));
 29	  const out = await runDebate("task", [a, b], 3);
 30	  assert.ok(out.aborted);
 31	  assert.match(out.aborted!, /only 1\/2 proposals succeeded/);
 32	  assert.match(out.transcript, /Debate aborted/);
 33	  assert.equal(reactions, 0);
 34	});
