 36	test("abort: both proposals failing lists both failures", async () => {
 37	  const a = fake("a", "v1", async () => fail("budget"));
 38	  const b = fake("b", "v2", async () => fail("timeout"));
 39	  const out = await runDebate("task", [a, b], 1);
 40	  assert.ok(out.aborted);
 41	  assert.match(out.aborted!, /a: budget/);
 42	  assert.match(out.aborted!, /b: timeout/);
 43	});
