 45	test("reaction context is clean: proposals included, cost footnotes excluded", async () => {
 46	  const seen: string[] = [];
 47	  const a = fake("a", "v1", async (prompt) => {
 48	    if (prompt.includes("debate so far")) seen.push(prompt);
 49	    return ok("proposal A says X");
 50	  });
 51	  const b = fake("b", "v2", async () => ok("proposal B says Y"));
 52	  const out = await runDebate("task", [a, b], 1);
 53	  assert.equal(out.aborted, undefined);
 54	  assert.equal(seen.length, 1);
 55	  assert.match(seen[0], /proposal A says X/);
 56	  assert.match(seen[0], /proposal B says Y/);
 57	  assert.doesNotMatch(seen[0], /cost:/);              // prompt hygiene
 58	  assert.match(out.transcript, /cost: \$0\.5000/);    // …but the artifact keeps cost
 59	  assert.equal(out.turns.length, 4);                  // 2 proposals + 2 reactions
 60	});
 61	
 62	test("respondeo: the judge runs after reactions and reads proposals + reactions", async () => {
 63	  let judgePrompt = "";
 64	  const a = fake("a", "v1", async () => ok("proposal A says X"));
 65	  const b = fake("b", "v2", async () => ok("proposal B says Y"));
 66	  const j = fake("opus", "v3", async (prompt) => {
 67	    if (prompt.includes("You are the JUDGE")) judgePrompt = prompt; // capture the respondeo call, not the redactio
 68	    return ok("STATUS: RESOLVED\n\nThe verdict.");
 69	  });
 70	  const out = await runDebate("task", [a, b], 1, undefined, j);
 71	  assert.equal(out.aborted, undefined);
 72	  // judge saw both proposals and the round-1 reactions
 73	  assert.match(judgePrompt, /proposal A says X/);
 74	  assert.match(judgePrompt, /Round 1 reaction/);
 75	  assert.doesNotMatch(judgePrompt, /cost:/); // clean context, like reactions
 76	  // recorded as a Respondeo turn in both turns[] and the transcript
 77	  assert.match(out.transcript, /## Respondeo — opus/);
 78	  assert.ok(out.turns.some((t) => t.title === "Respondeo — opus"));
 79	  assert.equal(out.respondeo?.status, "RESOLVED");
 80	  // …and a RESOLVED respondeo is now followed by the redactio (final deliverable)
 81	  assert.equal(out.turns.at(-1)?.title, "Final report — opus");
 82	  assert.ok(out.finalReport);
 83	});
 84	
 85	test("finalize: a RESOLVED respondeo triggers a final-report deliverable turn", async () => {
 86	  let redactioPrompt = "";
 87	  const a = fake("a", "v1", async () => ok("proposal A"));
 88	  const b = fake("b", "v2", async () => ok("proposal B"));
 89	  const j = fake("opus", "v3", async (prompt) => {
 90	    if (prompt.includes("FINAL DELIVERABLE")) {
 91	      redactioPrompt = prompt;
 92	      return ok("# The Plan\n\nStep 1: do the thing.");
 93	    }
 94	    return ok("STATUS: RESOLVED\n\nRuling: X wins.");
 95	  });
 96	  const out = await runDebate("Build a thing", [a, b], 0, undefined, j);
 97	  assert.equal(out.respondeo?.status, "RESOLVED");
 98	  assert.ok(out.finalReport, "finalReport present on RESOLVED");
 99	  assert.match(out.finalReport!.text, /The Plan/);
100	  // the synthesizer saw the quaestio, the transcript, and the determination
101	  assert.match(redactioPrompt, /Build a thing/);
102	  assert.match(redactioPrompt, /proposal A/);
103	  assert.match(redactioPrompt, /Ruling: X wins/);
104	  // recorded as the final turn + in the transcript artifact
105	  assert.equal(out.turns.at(-1)?.title, "Final report — opus");
106	  assert.match(out.transcript, /## Final report — opus/);
107	});
