109	test("finalize: NEEDS_INPUT does not produce a final report (the deliverable waits for the human)", async () => {
110	  const a = fake("a", "v1", async () => ok("proposal A"));
111	  const b = fake("b", "v2", async () => ok("proposal B"));
112	  const j = fake("opus", "v3", async () => ok("STATUS: NEEDS_INPUT\n\n## Quaestiones (for the human)\n- ?"));
113	  const out = await runDebate("task", [a, b], 0, undefined, j);
114	  assert.equal(out.finalReport, undefined);
115	  assert.doesNotMatch(out.transcript, /Final report/);
116	});
