118	test("finalize: no judge means no final report", async () => {
119	  const a = fake("a", "v1", async () => ok("proposal A"));
120	  const b = fake("b", "v2", async () => ok("proposal B"));
121	  const out = await runDebate("task", [a, b], 0); // no judge
122	  assert.equal(out.finalReport, undefined);
123	});
