125	test("finalize: a failing redactio is non-fatal (debate + respondeo still succeeded)", async () => {
126	  const a = fake("a", "v1", async () => ok("proposal A"));
127	  const b = fake("b", "v2", async () => ok("proposal B"));
128	  const j = fake("opus", "v3", async (prompt) =>
129	    prompt.includes("FINAL DELIVERABLE") ? fail("budget") : ok("STATUS: RESOLVED\n\nRuling."),
130	  );
131	  const out = await runDebate("task", [a, b], 0, undefined, j);
132	  assert.equal(out.respondeo?.status, "RESOLVED");
133	  assert.equal(out.finalReport, undefined);                 // no deliverable captured
134	  assert.match(out.transcript, /## Final report — opus/);   // …but the failed turn is recorded
135	});
