137	test("finalize: budget-exhausted redactio sets finalReportError.budgetExhausted", async () => {
138	  const budgetFail = (error: string): AgentResult => ({ ok: false, error, budgetExhausted: true });
139	  const a = fake("a", "v1", async () => ok("proposal A"));
140	  const b = fake("b", "v2", async () => ok("proposal B"));
141	  const j = fake("opus", "v3", async (prompt) =>
142	    prompt.includes("FINAL DELIVERABLE") ? budgetFail("Reached maximum budget ($2)") : ok("STATUS: RESOLVED\n\nRuling."),
143	  );
144	  const out = await runDebate("task", [a, b], 0, undefined, j);
145	  assert.equal(out.respondeo?.status, "RESOLVED");
146	  assert.equal(out.finalReport, undefined);
147	  assert.equal(out.finalReportError?.budgetExhausted, true);
148	  assert.match(out.finalReportError?.message ?? "", /Reached maximum budget/);
149	});
