 62	// Run a participant in ISOLATION. Isolation is a correctness requirement:
 63	// - Without repoPath: a throwaway temp dir, so agentic CLIs like agy cannot read
 64	//   sibling files — the contamination we caught in research/pre-m0-handrun.md.
 65	// - With repoPath: a DETACHED, THROWAWAY git worktree of HEAD — never the real
 66	//   checkout. Real-run lesson: evidence commands can write local runtime artifacts
 67	//   into the target repo. In a worktree those writes land in the disposable copy
 68	//   and die with it. Trade-off: agents see HEAD only (uncommitted changes are invisible) and
 69	//   untracked build artifacts (node_modules, …) are absent.
 70	export async function runIsolated(p: Participant, prompt: string, repoPath?: string): Promise<AgentResult> {
 71	  const dir = await mkdtemp(join(tmpdir(), "disputatio-"));
 72	  try {
 73	    if (!repoPath) return await p.run(prompt, dir);
 74	    const wt = join(dir, "wt");
 75	    await withGitLock(() => execFileAsync("git", ["-C", repoPath, "worktree", "add", "--detach", wt, "HEAD"]));
 76	    try {
 77	      return await p.run(prompt, wt);
 78	    } finally {
 79	      await withGitLock(async () => {
 80	        try { await execFileAsync("git", ["-C", repoPath, "worktree", "remove", "--force", wt]); }
 81	        catch { /* dir removal below + git's own prune cover the rest */ }
 82	      });
 83	    }
 84	  } finally {
 85	    await rm(dir, { recursive: true, force: true });
